/* Cognitive Care NER — isolated five-game runtime v6.
 * This runtime owns the game session completely. It does not depend on the
 * legacy game engines, Level 4 hooks, Mimo voice, or other phase modules.
 */
(()=>{
'use strict';
if(window.__CCNER_GAME_V6__)return;window.__CCNER_GAME_V6__=true;
const $=s=>document.querySelector(s), clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const shuffle=a=>{const x=[...a];for(let i=x.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[x[i],x[j]]=[x[j],x[i]]}return x};
const pick=a=>a[Math.floor(Math.random()*a.length)];
const games={
 sequence:{title:'Sequence Memory',cat:'MEMORY + ATTENTION',rounds:6,intro:'Watch the colours light up, then repeat the sequence from memory.'},
 stroop:{title:'Stroop Test',cat:'ATTENTION + CONCENTRATION',timed:true,intro:'Choose the ink colour, not the word.'},
 house:{title:'Around the House Sorting',cat:'DAILY-LIFE RECOGNITION',rounds:10,intro:'Put each everyday item where it belongs.'},
 pattern:{title:'Pattern Recognition',cat:'PATTERN RECOGNITION',rounds:15,intro:'Find the pattern and choose what comes next.'},
 spot:{title:'Spot the Difference',cat:'VISUAL ATTENTION',rounds:15,intro:'Look carefully, then spot what changed.'}
};
const keys=Object.keys(games);
const colors=[['red','Red'],['blue','Blue'],['green','Green'],['yellow','Yellow']];
const house=[['Writing Desk','Kitchen Drawer',['Stapler','Envelopes','Paperclips','Can Opener'],['Can Opener','Measuring Spoons','Oven Mitt','Tea Cup']],['Front Porch','Fireplace',['Rocking Chair','Welcome Mat','Firewood'],['Fire Poker','Firewood','Bellows','Rocking Chair']],['Bathroom','Bedroom',['Toothbrush','Soap','Comb','Toothpaste'],['Pillow','Alarm Clock','Blanket','Book']],['China Cabinet','Broom Closet',['Teacups','Serving Platter','Tea Pot','Saucer'],['Broom','Dustpan','Mop','Cleaning Cloth']]];
const patterns=[
 ['1, 2, 3, 4, 5','6',['5','6','7','8']],['2, 4, 6, 8, 10','12',['10','11','12','14']],['3, 6, 9, 12, 15','18',['15','16','18','21']],['2, 4, 8, 16, 32','64',['48','60','64','72']],['5, 10, 15, 20, 25','30',['25','28','30','35']],['1, 4, 9, 16, 25','36',['30','32','36','49']],['2, 5, 10, 17, 26','37',['34','36','37','39']],['10, 20, 40, 80, 160','320',['240','280','320','360']]
];
const spot=[['⭐','🌙','☀️','🌈','⚡','🍀','❤️','🔔'],['🎸','🎹','🥁','🎺','🎻','🪗','🎷','🪕'],['🍰','🧁','🍩','🍪','🎂','🍫','🍬','🍭'],['🍎','🍌','🍇','🍊','🍉','🥭','🍐','🍓'],['☕','🥄','🍚','🥣','🫖','🍵','🍞','🧂']];
let s={active:false,order:[],gi:0,game:null,round:1,results:[],started:0,locked:false,timer:null,seq:null,house:null,spot:null};
function css(){if($('#ccner-v6-style'))return;const st=document.createElement('style');st.id='ccner-v6-style';st.textContent=`
body.ccner-v6{background:radial-gradient(circle at 50% -10%,rgba(67,155,105,.18),transparent 35%),#06120c!important;color:#edf5ef!important}.ccner-v6 .topbar,.ccner-v6 footer,.ccner-v6 .home-strip,.ccner-v6 .info-grid,.ccner-v6 .section-label,.ccner-v6 .bottom-nav{display:none!important}.ccner-v6 .app-shell{width:min(900px,calc(100% - 28px));padding:12px 0 40px}.ccner-v6 .game-top{max-width:650px;margin:16px auto 12px}.ccner-v6 .game-top h2{color:#f7f2df;font-family:Georgia,serif;font-size:clamp(2rem,6vw,3rem)}.ccner-v6 .game-card{max-width:650px;margin:auto;padding:20px;background:#0b1e14;border:1px solid #31513f;border-radius:16px;box-shadow:0 18px 50px rgba(0,0,0,.3)}.ccner-v6 .game-prompt{color:#edf5ef}.v6-meta{display:flex;justify-content:space-between;color:#a9beb0;font-size:.8rem;margin:5px 0 14px}.v6-ai{color:#58cc8d;font-weight:900}.v6-rounds{display:flex;justify-content:center;gap:6px;margin:8px}.v6-rounds i{width:9px;height:9px;border-radius:50%;background:#35463c}.v6-rounds i.on{background:#55ca8d}.v6-status{text-align:center;font-weight:850;color:#cfe0d5;margin:12px}.v6-colors{display:grid;grid-template-columns:repeat(2,120px);gap:15px;justify-content:center;margin:18px}.v6-color{width:120px;height:100px;border-radius:18px;border:2px solid rgba(255,255,255,.14);cursor:pointer}.v6-color.red{background:#a72f40}.v6-color.blue{background:#315a9f}.v6-color.green{background:#278d50}.v6-color.yellow{background:#9d8012}.v6-color.flash{filter:brightness(1.6);box-shadow:0 0 0 5px rgba(255,255,255,.1),0 0 30px rgba(255,255,255,.25)}.v6-choice{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;max-width:560px;margin:18px auto}.v6-choice button,.v6-house button,.v6-next{min-height:58px;border:1px solid #31513f;border-radius:11px;background:#07150e;color:#e3eee7;font-weight:900;cursor:pointer;padding:10px}.v6-choice button:hover,.v6-house button.selected{background:#276f4b;border-color:#55ca8d}.v6-stroop{text-align:center;font-size:clamp(3.2rem,9vw,5.4rem);font-weight:950;margin:28px 0}.v6-timer{text-align:center;color:#63d096;font-size:1.25rem;font-weight:950}.v6-house{display:grid;gap:9px}.v6-house-row{display:grid;grid-template-columns:1fr 1fr;gap:7px;align-items:center;padding:8px;border:1px solid #284534;border-radius:10px;background:#08170f}.v6-house-row>span{font-weight:800}.v6-house-btns{display:grid;grid-template-columns:1fr 1fr;gap:6px}.v6-check,.v6-next{width:100%;margin-top:10px;background:#2b875a!important;color:#effff5!important}.v6-pattern{display:flex;justify-content:center;align-items:center;gap:8px;flex-wrap:wrap;margin:24px 0}.v6-pattern span{min-width:55px;min-height:55px;display:grid;place-items:center;border:1px solid #31513f;border-radius:11px;background:#0b2518;color:#59cd8d;font-weight:950;font-size:1.2rem}.v6-spot{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin:20px 0}.v6-spot button{min-height:76px;border:1px solid #31513f;border-radius:12px;background:#081a10;color:#fff;font-size:2rem;cursor:pointer}.v6-finish{text-align:center;padding:25px}.v6-finish strong{display:block;font-size:2.1rem;color:#5dd194;margin-bottom:10px}.v6-feedback{text-align:center;min-height:24px;color:#62d095;font-weight:900;margin-top:10px}.v6-mini{max-width:650px;margin:10px auto;padding:12px 15px;background:#f8f5ef;color:#6b625b;border-radius:20px;display:flex;gap:10px;align-items:center}.v6-mini b{color:#333}.v6-mini span:last-child{margin-left:auto;color:#298257;font-size:.7rem;font-weight:900}@media(max-width:600px){.v6-house-row{grid-template-columns:1fr}.v6-colors{grid-template-columns:repeat(2,100px)}.v6-color{width:100px;height:84px}.v6-spot{gap:7px}.v6-spot button{min-height:65px;font-size:1.7rem}}`;document.head.appendChild(st)}
function difficulty(k){try{const p=JSON.parse(localStorage.getItem('ccner-v6-difficulty')||'{}');return clamp(Number(p[k]||2),1,10)}catch(_){return 2}}
function adapt(k,ok,extra={}){try{const p=JSON.parse(localStorage.getItem('ccner-v6-difficulty')||'{}');const d=difficulty(k);const engine=window.CCNERRuleEngine;const failures=Number(p[k+'Failures']||0)+(ok?0:1);const successes=Number(p[k+'Successes']||0)+(ok?1:0);const decision=engine?.evaluate('GAME_RESULT',{game:k,accuracy:extra.accuracy??(ok?1:0),responseTime:extra.responseTime||0,skipped:Boolean(extra.skipped),consecutiveFailures:failures,consecutiveSuccesses:successes,fatigue:extra.fatigue||0});const direction=decision?.difficulty==='increase'?1:decision?.difficulty==='decrease'?-1:0;p[k]=clamp(d+direction,1,10);p[k+'Failures']=ok?0:failures;p[k+'Successes']=ok?successes:0;localStorage.setItem('ccner-v6-difficulty',JSON.stringify(p));engine?.setState({consecutiveFailures:p[k+'Failures'],consecutiveSuccesses:p[k+'Successes']});return p[k]}catch(_){return difficulty(k)} }
function setText(id,x){const e=$(id);if(e)e.textContent=x}
function clear(){if(s.timer){clearTimeout(s.timer);cancelAnimationFrame(s.timer);s.timer=null}}
function shell(){document.body.classList.add('ccner-v6');const g=games[s.game];setText('#gameCategory',g.cat);setText('#gameTitle',g.title);setText('#gamePrompt',g.intro);setText('#gameCounter',`${s.gi+1} of 5`);setText('#gameMimoText',`Adaptive practice · Difficulty ${difficulty(s.game)}/10`);const a=$('#gameArea');if(!a)return null;a.innerHTML=`<div class="v6-meta"><span class="v6-ai">AI-adaptive training</span><span>Difficulty ${difficulty(s.game)}/10</span><span>${g.timed?'2:00':'Test '+s.round+' / '+g.rounds}</span></div>`;return a}
function record(ok,extra={}){const ms=performance.now()-s.started;const responseTime=ms/1000;const level=adapt(s.game,ok,{...extra,responseTime});s.results.push({game:s.game,trial:s.round,correct:ok,seconds:responseTime,difficulty:level,...extra});}
function next(ok,extra={}){if(s.locked)return;s.locked=true;record(ok,extra);setText('#gameFeedback',ok?'Correct!':'Good try. Keep going.');setTimeout(()=>{if(!s.active)return;s.locked=false;if(s.game==='stroop'){if(performance.now()-s.gameStarted>=120000){finishGame();return}startRound();return}if(s.round>=games[s.game].rounds){finishGame();return}s.round++;startRound()},500)}
function sequence(a){const len=clamp(3+Math.floor((difficulty('sequence')-1)/2)+Math.floor((s.round-1)/2),3,10);const seq=Array.from({length:len},()=>pick(colors));s.seq={seq,pos:0};a.innerHTML+=`<div class="v6-rounds">${Array.from({length:6},(_,i)=>`<i class="${i<s.round?'on':''}"></i>`).join('')}</div><div class="v6-status" id="v6status">Watch carefully…</div><div class="v6-colors">${colors.map(c=>`<button class="v6-color ${c[0]}" data-c="${c[0]}" aria-label="${c[1]}"></button>`).join('')}</div>`;const tiles=[...a.querySelectorAll('.v6-color')];let i=0;const flash=()=>{tiles.forEach(t=>t.classList.remove('flash'));if(i<seq.length){tiles.find(t=>t.dataset.c===seq[i][0])?.classList.add('flash');i++;setTimeout(flash,600);return}setText('#v6status','Your turn — repeat the sequence.');tiles.forEach(t=>t.onclick=()=>{if(s.locked)return;if(t.dataset.c!==seq[s.seq.pos][0])return next(false);t.classList.add('flash');s.seq.pos++;if(s.seq.pos===seq.length)next(true,{length:seq.length});setTimeout(()=>t.classList.remove('flash'),160)});};setTimeout(flash,350)}
function stroop(a){const d=difficulty('stroop'),cs=colors.slice(0,clamp(2+Math.floor(d/3),2,4)),word=pick(cs),ink=pick(cs);a.innerHTML+=`<div class="v6-timer" id="v6timer"></div><div class="v6-stroop" style="color:${ink[0]==='red'?'#d34b59':ink[0]==='blue'?'#5d87d5':ink[0]==='green'?'#55c77d':'#d7bd4c'}">${word[1].toUpperCase()}</div><div class="v6-choice">${cs.map(c=>`<button data-c="${c[0]}">${c[1]}</button>`).join('')}</div>`;a.querySelectorAll('button').forEach(b=>b.onclick=()=>next(b.dataset.c===ink[0],{ink:ink[0],word:word[0]}));const tick=()=>{const left=Math.max(0,120-Math.floor((performance.now()-s.gameStarted)/1000));setText('#v6timer',`Time remaining: ${left}s`);if(left>0)s.timer=requestAnimationFrame(tick);else finishGame()};s.timer=requestAnimationFrame(tick)}
function houseGame(a){const p=house[(s.round-1)%house.length],items=shuffle([...p[2],...p[3]]).slice(0,Math.min(6,4+Math.floor(difficulty('house')/3)));s.house={p,items,ans:{}};a.innerHTML+=`<div class="v6-status">Choose where each item belongs.</div><div class="v6-house">${items.map((x,i)=>`<div class="v6-house-row" data-i="${i}"><span>${x}</span><div class="v6-house-btns"><button class="v6-house" data-g="a">${p[0]}</button><button class="v6-house" data-g="b">${p[1]}</button></div></div>`).join('')}</div><button class="v6-check" id="v6check" disabled>Check Answers</button>`;a.querySelectorAll('.v6-house-row').forEach(r=>r.querySelectorAll('button').forEach(b=>b.onclick=()=>{r.querySelectorAll('button').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');s.house.ans[r.dataset.i]=b.dataset.g;$('#v6check').disabled=Object.keys(s.house.ans).length!==items.length}));$('#v6check').onclick=()=>{let ok=0;items.forEach((x,i)=>{const expected=p[2].includes(x)?'a':'b';if(s.house.ans[i]===expected)ok++});next(ok===items.length,{items:items.length,correctItems:ok})}}
function pattern(a){const p=pick(patterns);a.innerHTML+=`<div class="v6-pattern">${p[0].split(', ').map(x=>`<span>${x}</span>`).join('')}<span>?</span></div><div class="v6-choice">${shuffle(p[2]).map(x=>`<button data-a="${x}">${x}</button>`).join('')}</div>`;a.querySelectorAll('button').forEach(b=>b.onclick=()=>next(b.dataset.a===p[1],{answer:p[1],chosen:b.dataset.a}))}
function spotGame(a){const base=pick(spot),n=clamp(4+Math.floor(difficulty('spot')/2),4,8),items=shuffle(base).slice(0,n),idx=Math.floor(Math.random()*items.length),alt=pick(['🍎','🥭','🍌','🍊','☕','💧','🥄','📖','🌸'].filter(x=>!items.includes(x)));s.spot={idx};a.innerHTML+=`<div class="v6-status" id="v6spot">Memorize these items…</div><div class="v6-spot" id="v6spotgrid">${items.map(x=>`<span>${x}</span>`).join('')}</div>`;setTimeout(()=>{if(!s.active)return;const changed=[...items];changed[idx]=alt;setText('#v6spot','Which item changed?');const grid=$('#v6spotgrid');grid.innerHTML=changed.map((x,i)=>`<button data-i="${i}">${x}</button>`).join('');grid.querySelectorAll('button').forEach(b=>b.onclick=()=>next(Number(b.dataset.i)===s.spot.idx,{changedIndex:s.spot.idx,chosen:Number(b.dataset.i)}))},Math.max(2500,6000-(difficulty('spot')-1)*300))}
function startRound(){clear();s.started=performance.now();const a=shell();if(!a)return;a.innerHTML=a.innerHTML;switch(s.game){case'sequence':sequence(a);break;case'stroop':stroop(a);break;case'house':houseGame(a);break;case'pattern':pattern(a);break;case'spot':spotGame(a);break}}
function finishGame(){clear();const rs=s.results.filter(x=>x.game===s.game),acc=rs.length?rs.filter(x=>x.correct).length/rs.length:0;const a=$('#gameArea');a.innerHTML=`<div class="v6-finish"><strong>${Math.round(acc*100)}% correct</strong><p>${s.game==='stroop'?'Two-minute attention practice complete.':`Completed ${rs.length} tests.`}</p><button class="v6-next" id="v6next">${s.gi<4?'Next game':'Finish session'}</button></div>`;$('#v6next').onclick=()=>{if(s.gi<4){s.gi++;s.game=s.order[s.gi];s.round=1;startRound()}else finishSession()}}
function finishSession(){clear();window.CCNERRuleEngine?.transition('game','completed');const acc=s.results.length?s.results.filter(x=>x.correct).length/s.results.length:0,avg=s.results.length?s.results.reduce((n,x)=>n+x.seconds,0)/s.results.length:0;try{const h=JSON.parse(localStorage.getItem('ccner-history')||'[]');h.push({date:new Date().toISOString(),score:Math.round(acc*100),accuracy:acc,avgTime:avg,level:1,results:s.results});localStorage.setItem('ccner-history',JSON.stringify(h.slice(-50)))}catch(_){}s.active=false;document.body.classList.remove('ccner-v6');window.CCNERRuleEngine?.transition('game','idle');const gv=$('#gameView'),rv=$('#resultsView');if(gv)gv.hidden=true;if(rv)rv.hidden=false;setText('#overallScore',Math.round(acc*100)+'%');setText('#overallAccuracy',Math.round(acc*100)+'%');setText('#gamesCompleted','5 / 5');setText('#avgTime',avg.toFixed(1)+'s');window.dispatchEvent(new CustomEvent('ccner:game-session-complete',{detail:{order:s.order,results:s.results,accuracy:acc,avgResponse:avg}}))}
function startSession(){if(s.active)return;css();window.CCNERRuleEngine?.transition('game','ready');window.CCNERRuleEngine?.transition('game','running');s={...s,active:true,order:shuffle(keys),gi:0,game:null,round:1,results:[]};s.game=s.order[0];const home=$('#homeView'),gv=$('#gameView'),rv=$('#resultsView');if(home)home.hidden=true;if(rv)rv.hidden=true;if(gv)gv.hidden=false;setText('#todayStatus','In progress');startRound()}
window.CCNER_VIDEO_GAMES=window.CCNER_VIDEO_GAMES||{};window.CCNER_VIDEO_GAMES.startSession=startSession;window.CCNER_VIDEO_GAMES.startGame=k=>{if(keys.includes(k)){s.active=true;s.game=k;s.round=1;$('#homeView').hidden=true;$('#gameView').hidden=false;startRound()}};window.CCNER_SAFE_START_SESSION=startSession;window.startSession=startSession;
})();
